const p = `<h2>\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0631\u0642\u0645\u064A\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0646\u062A\u0631\u0646\u062A</h2>
<p>\u0644\u0645 \u062A\u0643\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0645\u0648\u062C\u0648\u062F\u0629 \u062F\u0627\u0626\u0645\u064B\u0627\u060C \u0648\u0644\u0643\u0646 \u064A\u0645\u0643\u0646\u0646\u0627 \u0627\u0644\u0642\u0648\u0644 \u0628\u0623\u0645\u0627\u0646 \u0623\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0642\u062F \u062A\u0645 \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647\u0627 \u0643\u062B\u064A\u0631\u064B\u0627 \u0645\u0646\u0630 \u0638\u0647\u0648\u0631\u0647\u0627 \u0641\u064A \u0627\u0644\u0633\u0648\u0642. \u0648\u0644\u064A\u0633 \u0647\u0646\u0627\u0643 \u0637\u0644\u0628 \u0635\u063A\u064A\u0631 \u0648 \u0644\u0627 \u0627\u062E\u062A\u064A\u0627\u0631\u064A\u060C \u0648\u0627\u0644\u0622\u0646 \u0641\u064A \u0639\u0627\u0645 2023\u060C \u0644\u062F\u064A\u0646\u0627 \u0622\u0644\u0627\u0641 \u0648\u0622\u0644\u0627\u0641 \u0644\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u0645\u0646 \u0628\u064A\u0646\u0647\u0627 - \u0625\u0646\u0647\u0627 \u0645\u062C\u0631\u062F \u0645\u0633\u0623\u0644\u0629 \u0645\u0627 \u062A\u0631\u064A\u062F \u0648\u0645\u0627 \u0647\u064A \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u0630\u064A \u062A\u0631\u063A\u0628 \u0641\u064A \u0631\u0624\u064A\u062A\u0647\u0627 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648.</p>
<p>\u064A\u0628\u062D\u062B \u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u062F\u0627\u0626\u0645\u064B\u0627 \u0639\u0646 \u0634\u064A\u0621 \u062C\u062F\u064A\u062F\u060C \u0645\u0645\u0627 \u0633\u064A\u0633\u0627\u0639\u062F \u0641\u064A \u062C\u0639\u0644 \u062A\u062C\u0631\u0650\u0628\u0629 \u0627\u0644\u0644\u0639\u0628 \u0623\u0641\u0636\u0644 \u0628\u0643\u062B\u064A\u0631 \u0648\u0623\u0643\u062B\u0631 \u0633\u0647\u0648\u0644\u0629 \u0641\u064A \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647\u0627. \u0627\u0644\u0633\u0645\u0627\u062D \u0644\u0644\u0627\u0639\u0628 \u0628\u0627\u0644\u062A\u0631\u0643\u064A\u0632 \u0639\u0644\u0649 \u0627\u0644\u0645\u062A\u0639\u0629 \u0627\u0644\u0645\u0637\u0644\u0642\u0629 \u0644\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u060C \u0647\u0630\u0627 \u0635\u062D\u064A\u062D\u060C \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0646\u0641\u0633\u0647\u0627.</p>

<div class="other-info">
  <p>\u0644\u0647\u0630\u0627 \u0627\u0644\u0633\u0628\u0628 \u0633\u0646\u062E\u0628\u0631\u0643 \u0627\u0644\u0622\u0646 \u0628\u0643\u0644 \u0645\u0627 \u062A\u062D\u062A\u0627\u062C \u0644\u0645\u0639\u0631\u0641\u062A\u0647 \u062D\u0648\u0644 \u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u0623\u0648 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0628\u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0623\u0648 \u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646\u060C \u0623\u064A\u064B\u0627 \u0643\u0627\u0646 \u0645\u0627 \u062A\u0631\u064A\u062F \u062A\u0633\u0645\u064A\u062A\u0647.</p>
  <h2>\u0645\u0627\u0647\u064A \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648\u061F</h2>
  <p>\u0642\u0628\u0644 \u0645\u0646\u0627\u0642\u0634\u0629 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0644\u0639\u0628\u0647\u0627\u060C \u0639\u0644\u064A\u0643 \u0623\u0648\u0644\u0627\u064B \u0623\u0646 \u062A\u0641\u0647\u0645 \u0645\u0627\u0647\u064A\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0648\u0644\u0645\u0627\u0630\u0627 \u064A\u0641\u0636\u0644 \u0627\u0644\u0646\u0627\u0633 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u062E\u0650\u064A\u0627\u0631 \u0627\u0644\u062F\u0641\u0639 \u0647\u0630\u0627 \u0639\u0646\u062F\u0645\u0627 \u062A\u0644\u0639\u0628 \u0623\u0644\u0639\u0627\u0628\u0647\u0627 \u0627\u0644\u0645\u0641\u0636\u0644\u0629.</p>
  <p>\u0646\u0645\u062A \u0639\u0645\u0644\u0629 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0648\u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0627\u0644\u0623\u062E\u0631\u0649 \u0648\u0635\u0646\u0639\u062A \u0627\u0633\u0645\u064B\u0627 \u0643\u0628\u064A\u0631\u064B\u0627 \u0644\u0623\u0646\u0641\u0633\u0647\u0627 \u0639\u0644\u0649 \u0645\u062F\u0627\u0631 \u0627\u0644\u0633\u0646\u0648\u0627\u062A \u0627\u0644\u0642\u0644\u064A\u0644\u0629 \u0627\u0644\u0645\u0627\u0636\u064A\u0629. \u0639\u0646\u062F\u0645\u0627 \u0628\u062F\u0623\u062A\u060C \u0643\u0627\u0646 \u0634\u0631\u0627\u0621 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0645\u062E\u0627\u0637\u0631\u0629 \u0648\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064A\u0646 \u062E\u0627\u0637\u0631\u0648\u0627 \u0647\u0645 \u0627\u0644\u0645\u0633\u062A\u0641\u064A\u062F\u0648\u0646 \u0645\u0646\u0647\u0627 \u0627\u0644\u0622\u0646. \u064A\u064F\u062D\u062A\u0645\u0644 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u0645\u0635\u062F\u0631 \u062F\u062E\u0644 \u0639\u0627\u062F\u0644 \u0645\u0646 \u0635\u0639\u0648\u062F\u0647 \u0648\u0647\u0628\u0648\u0637\u0647 \u0641\u064A \u0627\u0644\u0633\u0648\u0642 \u060C \u0648\u0623\u0641\u0636\u0644 \u0645\u0627 \u0641\u064A \u0630\u0644\u0643 \u0643\u0644\u0647 - \u0647\u0648 \u0623\u0646\u0647 \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0642\u064A\u0627\u0645 \u0628\u0630\u0644\u0643 \u062F\u0648\u0646 \u0627\u0644\u0643\u0634\u0641 \u0639\u0646 \u0647\u0648\u064A\u062A\u0643 \u062A\u0645\u0627\u0645\u064B\u0627.</p>
  <p>\u0631\u0628\u0645\u0627 \u0643\u0627\u0646\u062A \u0645\u062E\u0627\u0637\u0631\u0629 \u0641\u064A \u0630\u0644\u0643 \u0627\u0644\u0648\u0642\u062A\u060C \u0648\u0644\u0643\u0646 \u0627\u0644\u064A\u0648\u0645 \u064A\u0645\u0643\u0646\u0643 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0645\u062B\u0644 \u0623\u064A \u062E\u0650\u064A\u0627\u0631 \u062F\u0641\u0639 \u0622\u062E\u0631. \u0627\u0644\u0642\u0644\u064A\u0644 \u0645\u0646\u0647\u0645 \u0644\u0627 \u064A\u0642\u0628\u0644\u0648\u0646 \u0630\u0644\u0643\u060C \u0644\u0643\u0646 \u0643\u0627\u0632\u064A\u0646\u0648 Btc \u062D\u0642\u0642 \u0646\u062C\u0627\u062D\u064B\u0627 \u0643\u0628\u064A\u0631\u064B\u0627 \u0648\u0627\u0633\u062A\u0645\u0631 \u0641\u064A \u0627\u0644\u0646\u0645\u0648 \u0639\u0644\u0649 \u0645\u062F\u0627\u0631 \u0627\u0644\u0633\u0646\u0648\u0627\u062A \u0627\u0644\u062E\u0645\u0633 \u0627\u0644\u0645\u0627\u0636\u064A\u0629 \u0623\u0648 \u0623\u0643\u062B\u0631.</p>
  <p>\u0648 \u0623\u0641\u0636\u0644 \u0645\u0627 \u0641\u064A \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0643\u0645\u0643\u0627\u0641\u0623\u0629 \u0625\u064A\u062F\u0627\u0639 \u0623\u0648 \u0643\u062E\u064A\u0627\u0631 \u062F\u0641\u0639\u060C \u0639\u0645\u0648\u0645\u064B\u0627\u060C \u0647\u0648 \u0623\u0646\u0647 \u064A\u0645\u0643\u0646\u0643 \u0628\u0633\u0647\u0648\u0644\u0629 \u0631\u0628\u0637 \u062D\u0633\u0627\u0628 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0627\u0644\u062E\u0627\u0635 \u0628\u0643 \u0628\u062D\u0633\u0627\u0628\u0643 \u0627\u0644\u0645\u0635\u0631\u0641\u064A \u0648\u0627\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0648\u0627\u0644\u0641\u0648\u0631\u064A \u0625\u0644\u0649 \u0623\u0641\u0636\u0644 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648.</p>

  <h2>\u0647\u0644 \u064A\u0645\u0643\u0646\u0643 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0641\u064A \u062C\u0645\u064A\u0639 \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A\u061F</h2>
  <p>\u064A\u062D\u0644\u0645 \u062C\u0645\u064A\u0639 \u0627\u0644\u0644\u0627\u0639\u0628\u064A\u0646 \u0628\u0623\u0646 \u062C\u0645\u064A\u0639 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0645\u062E\u062A\u0644\u0641\u0629 \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0627\u0644\u062A\u064A \u062A\u062C\u062F\u0647\u0627 \u0633\u062A\u0633\u0645\u062D \u0644\u0643 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0648\u063A\u064A\u0631\u0647\u0627 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0644\u0644\u0625\u064A\u062F\u0627\u0639 \u0648\u0627\u0644\u0633\u062D\u0628. \u0644\u0633\u0648\u0621 \u0627\u0644\u062D\u0638\u060C \u0627\u0644\u062D\u0642\u064A\u0642\u0629 \u0627\u0644\u0645\u062D\u0632\u0646\u0629 \u0647\u064A \u0623\u0646 \u0639\u062F\u062F\u064B\u0627 \u0642\u0644\u064A\u0644\u0627\u064B \u062C\u062F\u064B\u0627 \u0645\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u064A\u0642\u0628\u0644\u0647\u0627. \u0644\u0643\u0646 \u0627\u0644\u062E\u0628\u0631 \u0627\u0644\u0633\u0627\u0631 \u0647\u0648 \u0623\u0646 \u0623\u0641\u0636\u0644 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0633\u062A\u0645\u062A\u0644\u0643 \u0648\u0627\u062D\u062F\u0629 \u0623\u0648 \u0623\u062E\u0631\u0649 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644 \u0641\u064A \u0627\u0644\u0625\u064A\u062F\u0627\u0639\u0627\u062A. \u0639\u0646\u062F\u0645\u0627 \u064A\u062A\u0639\u0644\u0642 \u0627\u0644\u0623\u0645\u0631 \u0628\u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u0633\u062D\u0628\u060C \u064A\u0635\u0639\u0628 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0643\u0627\u0632\u064A\u0646\u0648. \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u062C\u062D \u060C \u0633\u064A\u062A\u0639\u064A\u0646 \u0639\u0644\u064A\u0643 \u0627\u062E\u062A\u064A\u0627\u0631 \u0623\u062D\u062F \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u0623\u062E\u0631\u0649. \u0623\u0643\u062B\u0631 \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646 \u062F\u0645\u062C\u0647\u0627 \u0645\u0639 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0648\u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0647\u064A \u0627\u0644\u062A\u062D\u0648\u064A\u0644 \u0627\u0644\u0645\u0635\u0631\u0641\u064A \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0625\u0644\u0649 \u062D\u0633\u0627\u0628\u0643 \u0627\u0644\u0645\u0635\u0631\u0641\u064A.</p>
  <p>\u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0645\u0628\u062A\u062F\u0626\u064A\u0646 \u0647\u0646\u0627\u0643\u060C \u0633\u0646\u062A\u0631\u0643 \u0628\u0639\u0636 \u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0644\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0623\u062E\u0631\u0649 \u0644\u0644\u0646\u0638\u0631 \u0641\u064A\u0647\u0627 \u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0631\u063A\u0628 \u0641\u064A \u062A\u062C\u0631\u0650\u0628\u0629 \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0645\u0631\u0627\u0647\u0646\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u0628\u0644 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629. \u0644\u062F\u064A\u0646\u0627 \u0643\u0627\u0632\u064A\u0646\u0648 Doge \u0648 Shiba Casino \u0648 Solana Casino\u060C \u0648\u0643\u0644\u0647\u0627 \u062A\u0633\u062A\u062D\u0642 \u0648\u0642\u062A\u0643. \u0633\u0648\u0641 \u064A\u062C\u0644\u0628\u0648\u0646 \u0627\u0644\u0625\u062B\u0627\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u0639\u0649 \u0625\u0644\u064A\u0647\u0627 \u062C\u0645\u064A\u0639\u064B\u0627. \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u062F\u0641\u0639 \u0628\u0639\u0645\u0644\u0629 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 - \u0648\u0623\u0641\u0636\u0644 \u062C\u0632\u0621 \u0647\u0648 \u0623\u0646\u0647\u0645 \u064A\u0645\u0646\u062D\u0648\u0646 \u062C\u0645\u064A\u0639\u064B\u0627 \u0645\u0643\u0627\u0641\u0623\u0629 \u0625\u064A\u062F\u0627\u0639 \u0631\u0627\u0626\u0639\u0629 \u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u062E\u0627\u0635 \u0628\u0647\u0645 \u0648\u0627\u0644\u0627\u0646\u0636\u0645\u0627\u0645 \u0625\u0644\u0649 \u0639\u0627\u0644\u0645 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0628\u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648.</p>
  
  <h2>\u0645\u0627\u0647\u064A \u0645\u0632\u0627\u064A\u0627 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0628\u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648\u061F</h2>
  <ul>
    <li>\u0639\u062F\u0645 \u0627\u0644\u0643\u0634\u0641 \u0639\u0646 \u0647\u0648\u064A\u062A\u0643 - \u0639\u0646\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u0641\u064A \u0627\u0644\u0633\u0648\u0642 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A\u060C \u0644\u0627 \u062A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u062A\u0642\u062F\u064A\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u064A\u0645\u0643\u0646 \u0623\u0646 \u062A\u0633\u0627\u0639\u062F \u0641\u064A \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0643. \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0621 \u0628\u0646\u0633\u0628\u0629 100\u066A \u062E\u0644\u0641 \u0634\u0627\u0634\u0629 \u0627\u0644\u062D\u0627\u0633\u0648\u0628 \u0648\u0644\u0627 \u062A\u062A\u062E\u0644\u0649 \u0639\u0646 \u0627\u0633\u0645\u0643 \u0627\u0644\u0623\u0648\u0644 \u0623\u0628\u062F\u064B\u0627. \u0647\u0630\u0647 \u0647\u064A \u0627\u0644\u0646\u0642\u0637\u0629 \u0627\u0644\u0623\u0643\u062B\u0631 \u0645\u0628\u064A\u0639\u064B\u0627 \u0644\u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0645\u0646 \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0644\u0644\u0643\u062B\u064A\u0631\u064A\u0646.</li>
    <li>\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u062C\u0645\u064A\u0639 \u0623\u0646\u062D\u0627\u0621 \u0627\u0644\u0639\u0627\u0644\u0645 - \u0643\u0645\u0627 \u0646\u0639\u0644\u0645\u060C \u062A\u062A\u0648\u0641\u0631 \u0627\u0644\u0639\u062F\u064A\u062F \u0645\u0646 \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0644\u0644\u0628\u0639\u0636 \u0641\u0642\u0637\u060C \u0648\u0644\u064A\u0633 \u0644\u0644\u062C\u0645\u064A\u0639\u060C \u0648\u0642\u062F \u064A\u0643\u0648\u0646 \u0627\u0644\u0623\u0645\u0631 \u0645\u062D\u0628\u0637\u064B\u0627 \u0644\u0644\u063A\u0627\u064A\u0629 \u0648\u064A\u0645\u0643\u0646 \u0623\u0646 \u064A\u0645\u062B\u0644 \u062A\u062D\u062F\u064A\u064B\u0627 \u0644\u0628\u0639\u0636 \u0627\u0644\u0644\u0627\u0639\u0628\u064A\u0646 \u0641\u064A \u0628\u0639\u0636 \u0627\u0644\u0628\u0644\u062F\u0627\u0646 - \u0644\u0623\u0646 \u0642\u064A\u0648\u062F\u0647\u0645 \u0639\u0644\u0649 \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u062A\u0645\u0646\u0639\u0647\u0645 \u0628\u0634\u062F\u0629 \u0645\u0646 \u0627\u0644\u0644\u0639\u0628 \u0639\u0644\u0649 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0648\u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062A\u064A \u064A\u0631\u064A\u062F\u0648\u0646 \u0627\u0644\u0644\u0639\u0628 \u0639\u0644\u064A\u0647\u0627. \u0645\u0639 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0648\u063A\u064A\u0631\u0647\u0627 \u0645\u0646 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0645\u0634\u0641\u0631\u0629\u060C \u0633\u0648\u0641 \u064A\u0632\u064A\u0644\u0648\u0646 \u0647\u0630\u0627 \u0627\u0644\u062D\u062F \u0648\u0644\u0646 \u064A\u0636\u0637\u0631\u0648\u0627 \u0628\u0639\u062F \u0627\u0644\u0622\u0646 \u0625\u0644\u0649 \u0627\u0644\u0628\u062D\u062B \u0641\u064A \u0623\u064A \u0645\u0643\u0627\u0646 \u0622\u062E\u0631 \u0644\u0644\u0627\u0633\u062A\u0645\u062A\u0627\u0639.</li>
    <li>\u0627\u0644\u062A\u062D\u0642\u0642 - \u0645\u0641\u0633\u062F \u0627\u0644\u062D\u0641\u0644\u0629 \u0627\u0644\u062D\u0642\u064A\u0642\u064A \u0647\u0648 \u0639\u0646\u062F\u0645\u0627 \u064A\u062A\u0639\u064A\u0646 \u0639\u0644\u064A\u0643 \u0645\u0644\u0621 \u0627\u0644\u0643\u062B\u064A\u0631 \u0645\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0645\u062A\u0639\u0629. \u0627\u0644\u062C\u0648\u0627\u0628 \u0627\u0644\u0628\u0633\u064A\u0637 \u0647\u0648 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629\u060C \u0648\u0644\u0646 \u062A\u062D\u062A\u0627\u062C \u0628\u0639\u062F \u0627\u0644\u0622\u0646 \u0625\u0644\u0649 \u062A\u062C\u0631\u0650\u0628\u0629 \u0630\u0644\u0643.</li>
    <li>\u0631\u0633\u0648\u0645 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062A - \u062D\u0633\u0646\u064B\u0627\u060C \u0646\u062D\u0646 \u0646\u062A\u0641\u0647\u0645 \u0623\u0646 \u0643\u0644 \u0634\u062E\u0635 \u064A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u0643\u0633\u0628 \u0627\u0644\u0645\u0627\u0644 \u0648\u0623\u0646\u0647 \u0644\u064A\u0633 \u0643\u0644\u0651\u0645\u0627 \u064A\u062A\u0645 \u062A\u063A\u0637\u064A\u062A\u0647 \u0628\u0648\u0627\u0633\u0637\u0629 \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062A\u060C \u0648\u0645\u0627 \u0625\u0644\u0649 \u0630\u0644\u0643\u060C \u0627\u0644\u062A\u064A \u062A\u0639\u0645\u0644 \u0641\u064A \u0627\u0644\u062E\u0644\u0641\u064A\u0629 \u0648\u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u0642\u064A\u0627\u0633\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0623\u062A\u064A \u0645\u0639 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629. \u0644\u0643\u0646\u0646\u0627 \u0646\u0639\u0644\u0645 \u0623\u064A\u0636\u064B\u0627 \u0623\u0646 \u0628\u0639\u0636 \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u062A\u0643\u0648\u0646 \u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u062A\u064A \u064A\u062A\u0645 \u0641\u0631\u0636\u0647\u0627 \u0639\u0644\u0649 \u0639\u0645\u0644\u0627\u0626\u0647\u0645 \u062B\u0642\u064A\u0644\u0629 \u0639\u0646\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647\u0645 \u0644\u062E\u062F\u0645\u0627\u062A\u0647\u0645. \u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u0643\u062E\u064A\u0627\u0631 \u062F\u0641\u0639\u060C \u0641\u0644\u0646 \u062A\u062C\u062F \u0647\u0630\u0647 \u0627\u0644\u0645\u0634\u0643\u0644\u0629. \u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u0643\u062E\u064A\u0627\u0631 \u062F\u0641\u0639\u060C \u0641\u0644\u0646 \u062A\u062C\u062F \u0647\u0630\u0647 \u0627\u0644\u0645\u0634\u0643\u0644\u0629.</li>
  </ul>
  
  <h2>\u0639\u064A\u0648\u0628 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0628\u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629</h2>
  <ul>
    <li>\u0644\u0627 \u062A\u0648\u062C\u062F \u0639\u0645\u0644\u064A\u0627\u062A \u0631\u062F \u0627\u0644\u0645\u0628\u0627\u0644\u063A \u0627\u0644\u0645\u062F\u0641\u0648\u0639\u0629 / \u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u062A\u0631\u0627\u062C\u0639 - \u0644\u0633\u0648\u0621 \u0627\u0644\u062D\u0638\u060C \u0644\u0627 \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0639\u0646\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u062E\u0650\u064A\u0627\u0631 \u0627\u0644\u062F\u0641\u0639 \u0647\u0630\u0627. \u0628\u0645\u062C\u0631\u062F \u062A\u0623\u0643\u064A\u062F \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629 \u0639\u0644\u0649 \u062D\u0633\u0627\u0628\u0643 \u0648\u062A\u0631\u0643\u0647\u0627 \u0645\u062D\u0641\u0638\u062A\u0643\u060C \u0647\u0630\u0627 \u0643\u0644 \u0634\u064A\u0621. \u0644\u0630\u0627 \u062A\u062D\u0642\u0642 \u0645\u0646 \u0641\u062D\u0635 \u062E\u0644\u0641\u064A\u0629 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0623\u0648 \u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0627\u0644\u0630\u064A \u062A\u0631\u064A\u062F \u0642\u0636\u0627\u0621 \u0648\u0642\u062A\u0643 \u0648\u0623\u0645\u0648\u0627\u0644\u0643 \u0641\u064A\u0647 \u0644\u0623\u0646\u0643 \u0644\u0627 \u062A\u062A\u0645\u062A\u0639 \u0628\u0646\u0641\u0633 \u0627\u0644\u0623\u0645\u0627\u0646 \u0645\u062B\u0644 \u0628\u0637\u0627\u0642\u0627\u062A \u0627\u0644\u0627\u0626\u062A\u0645\u0627\u0646 \u0648\u0637\u0631\u0642 \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u062A\u0642\u0644\u064A\u062F\u064A\u0629 \u0627\u0644\u0623\u062E\u0631\u0649.</li>
    <li>\u0644\u0627 \u060C "\u0627\u0644\u0632\u0628\u0648\u0646 \u062F\u0627\u0626\u0645\u064B\u0627 \u0639\u0644\u0649 \u062D\u0642" - \u0639\u0646\u062F\u0645\u0627 \u064A\u062A\u0639\u0644\u0642 \u0627\u0644\u0623\u0645\u0631 \u0628\u0645\u0634\u0627\u0643\u0644 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062A \u060C \u062A\u0645 \u0648\u0635\u0641 \u062E\u062F\u0645\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0628\u0623\u0646\u0647\u0627 \u0644\u064A\u0633\u062A \u0627\u0644\u0623\u0641\u0636\u0644. \u0625\u0646\u0647\u0645 \u064A\u062F\u064A\u0631\u0648\u0646 \u0627\u062A\u0635\u0627\u0644\u0627\u062A \u062C\u064A\u062F\u0629 \u0645\u0639 \u062C\u0645\u064A\u0639 \u0639\u0645\u0644\u0627\u0626\u0647\u0645\u060C \u0648\u0644\u0646 \u062A\u062A\u0631\u0643 \u0644\u0641\u0631\u0632\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0623\u0648 \u0634\u064A\u0621 \u0622\u062E\u0631. \u0644\u0643\u0646 \u0641\u0631\u0635 \u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0628\u0645\u062C\u0631\u062F \u062A\u0631\u0643\u0647\u0627 \u062D\u0633\u0627\u0628\u0643 \u0636\u0626\u064A\u0644\u0629 \u0644\u0644\u063A\u0627\u064A\u0629. \u0644\u0630\u0644\u0643 \u0639\u0644\u064A\u0643 \u0623\u0646 \u062A\u062A\u062D\u0642\u0642 \u0645\u0646 \u0648\u0642\u062A \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647 \u0648\u0627\u0644\u0645\u0642\u062F\u0627\u0631 \u0627\u0644\u0630\u064A \u062A\u0631\u063A\u0628 \u0641\u064A \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647 \u0648\u0623\u0646\u0647 \u064A\u0645\u0643\u0646\u0643 \u062D\u0642\u064B\u0627 \u0627\u0644\u0648\u062B\u0648\u0642 \u0628\u0627\u0644\u0634\u062E\u0635 / \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u0648\u0645 \u0628\u0627\u0644\u062F\u0641\u0639 \u0644\u0647\u0627.</li>
  </ul>
  
  <h2>\u0643\u064A\u0641 \u064A\u0645\u0643\u0646\u0646\u064A \u0627\u0644\u062A\u0623\u0643\u062F \u0645\u0646 \u0623\u0646 \u0645\u0648\u0642\u0639 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0622\u0645\u0646\u061F</h2>
  <p>\u0645\u0639\u0638\u0645 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0627\u0644\u064A\u0648\u0645 \u0622\u0645\u0646\u0629\u060C \u0648\u0644\u0627 \u062F\u0627\u0639\u064A \u0644\u0644\u0642\u0644\u0642 \u0628\u0634\u0623\u0646 \u0642\u0636\u0627\u0621 \u0648\u0642\u062A\u0643 \u0641\u064A\u0647\u0627. \u0648\u0645\u0639 \u0630\u0644\u0643\u060C \u0647\u0646\u0627\u0643 \u0628\u0639\u0636 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0647\u062A\u0645 \u0628\u0645\u0635\u0644\u062D\u062A\u0643. \u0644\u0647\u0630\u0627 \u0627\u0644\u0633\u0628\u0628 \u062A\u062D\u062A\u0627\u062C \u062F\u0627\u0626\u0645\u064B\u0627 \u0625\u0644\u0649 \u0625\u062C\u0631\u0627\u0621 \u0641\u062D\u0635 \u0627\u0644\u062E\u0644\u0641\u064A\u0629 \u062D\u062A\u0649 \u0639\u0646\u062F\u0645\u0627 \u064A\u062A\u0639\u0644\u0642 \u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0628\u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648\u060C \u0623\u0648 \u064A\u062C\u0628 \u0623\u0646 \u0646\u0642\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644 \u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0631\u064A\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0644\u0644\u0645\u0642\u0627\u0645\u0631\u0629. \u0644\u0627 \u064A\u0648\u062C\u062F \u0623\u0645\u0627\u0646 \u0625\u0636\u0627\u0641\u064A\u060C \u0648\u0639\u0646\u062F\u0645\u0627 \u064A\u062A\u0631\u0643 \u0627\u0644\u0645\u0627\u0644 \u0645\u062D\u0641\u0638\u062A\u0643\u060C \u0644\u0646 \u064A\u0643\u0648\u0646 \u0644\u062F\u064A\u0643 \u0627\u0644\u0643\u062B\u064A\u0631 \u0645\u0646 \u0627\u0644\u0641\u0631\u0635 \u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0627\u0644\u0623\u0645\u0648\u0627\u0644.</p>
  <p>\u0644\u062D\u0633\u0646 \u0627\u0644\u062D\u0638\u060C \u0647\u0646\u0627\u0643 \u0637\u0631\u0642 \u0644\u0645\u0639\u0631\u0641\u0629 \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0628\u0625\u0645\u0643\u0627\u0646\u0643 \u0627\u0644\u0648\u062B\u0648\u0642 \u062D\u0642\u064B\u0627 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0630\u064A \u062A\u0631\u063A\u0628 \u0641\u064A \u0642\u0636\u0627\u0621 \u0648\u0642\u062A\u0643 \u0641\u064A\u0647. \u0623\u0641\u0636\u0644 \u0637\u0631\u064A\u0642\u0629 \u0647\u064A \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0644\u062F\u064A\u0647 \u062A\u0631\u062E\u064A\u0635 \u0635\u0627\u0644\u062D \u0644\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A. \u062A\u062D\u062A\u0627\u062C \u062C\u0645\u064A\u0639 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0625\u0644\u0649 \u0647\u0630\u0627 \u0644\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u062E\u0627\u0635 \u0628\u0647\u0645 \u0628\u0634\u0643\u0644 \u0642\u0627\u0646\u0648\u0646\u064A\u060C \u0648\u0647\u0648 \u0644\u064A\u0633 \u0645\u062C\u0627\u0646\u064A\u064B\u0627\u060C \u0644\u0630\u0644\u0643 \u0644\u0646 \u064A\u0643\u0648\u0646 \u0634\u064A\u0626\u064B\u0627 \u064A\u062A\u0645 \u0627\u062E\u0641\u0627\u0626\u0647. \u062A\u062E\u062A\u0627\u0631 \u0628\u0639\u0636 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0623\u0643\u062B\u0631 \u0645\u0646 \u0648\u0627\u062D\u062F \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u062A\u0631\u0627\u062E\u064A\u0635. \u0647\u0630\u0647 \u0639\u0644\u0627\u0645\u0629 \u062D\u0645\u0631\u0627\u0621 \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0628\u0639\u0636\u060C \u0648\u0646\u062D\u0646 \u0647\u0646\u0627 \u0644\u0646\u062E\u0628\u0631\u0643 \u0623\u0646\u0647\u0627 \u0644\u064A\u0633\u062A \u0639\u0644\u0627\u0645\u0629 \u062D\u0645\u0631\u0627\u0621. \u064A\u0645\u0643\u0646 \u0623\u0646 \u064A\u062D\u0635\u0644 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0639\u0644\u0649 \u0627\u0644\u0639\u062F\u064A\u062F \u0645\u0646 \u0627\u0644\u062A\u0631\u0627\u062E\u064A\u0635 \u0643\u0645\u0627 \u064A\u062D\u0644\u0648 \u0644\u0647\u0645\u060C \u0648\u0644\u0643\u0646 \u064A\u0645\u0643\u0646\u0647\u0645 \u0623\u064A\u0636\u064B\u0627 \u0627\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0648\u0627\u062D\u062F.</p>
  <p>\u0623\u064A\u0636\u064B\u0627\u060C \u064A\u0639\u062F \u0627\u0644\u0628\u062D\u062B \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0644\u0625\u0644\u0642\u0627\u0621 \u0646\u0638\u0631\u0629 \u0639\u0644\u0649 \u0645\u0627 \u064A\u0642\u0648\u0644\u0647 \u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u0627\u0644\u0622\u062E\u0631\u0648\u0646 \u0641\u0643\u0631\u0629 \u062C\u064A\u062F\u0629 \u062F\u0627\u0626\u0645\u064B\u0627. \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u063A\u064A\u0631 \u0639\u0627\u062F\u0644\u060C \u0641\u0644\u0646 \u062A\u0643\u0648\u0646 \u0623\u0648\u0644 \u0636\u062D\u064A\u0629 - \u0644\u0630\u0644\u0643 \u0633\u064A\u0643\u0648\u0646 \u0647\u0646\u0627\u0643 \u0646\u0648\u0639 \u0645\u0646 \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0627\u062A \u0627\u0644\u062A\u064A \u062A\u062E\u0628\u0631\u0643 \u0628\u0645\u0627 \u062D\u062F\u062B \u0648\u0645\u0627 \u062A\u0645 \u0641\u0639\u0644\u0647 \u062D\u064A\u0627\u0644 \u0630\u0644\u0643. \u0627\u0633\u062A\u062E\u062F\u0645 \u062D\u062F\u0633\u0643 \u0648 \u0627\u0644\u0645\u0646\u0637\u0642\u060C \u0648\u0625\u0630\u0627 \u0634\u0639\u0631\u062A \u0628\u0634\u064A\u0621 \u0645\u0627 \u0628\u0634\u0623\u0646 \u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629\u060C \u0641\u0647\u0646\u0627\u0643 \u0627\u0644\u0643\u062B\u064A\u0631. \u0627\u062E\u062A\u0631 \u0648\u0627\u062D\u062F\u0629 \u0645\u062E\u062A\u0644\u0641\u0629\u060C \u0648\u0644\u0627 \u062F\u0627\u0639\u064A \u0644\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0628\u0627\u0644\u0625\u064A\u0645\u0627\u0646.</p>

  <h2>\u0647\u0644 \u0645\u0627 \u0632\u0644\u062A \u062A\u062D\u0635\u0644 \u0639\u0644\u0649 \u0645\u0643\u0627\u0641\u0622\u062A \u0625\u0630\u0627 \u0623\u0648\u062F\u0639\u062A \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629\u061F</h2>
  <p>\u064A\u0645\u0643\u0646\u0646\u0627 \u0627\u0644\u0642\u0648\u0644 \u0623\u0646 \u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0648\u0627\u0644\u0625\u062B\u0627\u0631\u0629 \u0648\u0627\u0644\u0645\u062A\u0639\u0629 \u0648\u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0647\u064A \u0627\u0644\u062A\u064A \u062A\u062C\u0644\u0628 \u0627\u0644\u0644\u0627\u0639\u0628\u064A\u0646 \u0625\u0644\u0649 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0645\u062E\u062A\u0644\u0641\u0629 \u060C \u0644\u0643\u0646\u0646\u0627 \u0646\u0639\u0644\u0645 \u062C\u0645\u064A\u0639\u064B\u0627 \u0623\u0646\u0647\u0627 \u0633\u062A\u0643\u0648\u0646 \u0643\u0630\u0628\u0629. \u064A\u0631\u064A\u062F \u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u0645\u0643\u0627\u0641\u0622\u062A \u0648\u0627\u0644\u0643\u062B\u064A\u0631 \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062A \u0644\u0645\u0633\u0627\u0639\u062F\u062A\u0647\u0645 \u0641\u064A \u0637\u0631\u064A\u0642\u0647\u0645 \u0644\u0644\u0641\u0648\u0632 \u0627\u0644\u0643\u0628\u064A\u0631. \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062A \u0647\u064A \u0645\u062B\u0644 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0645\u062C\u0627\u0646\u064A\u0629\u060C \u0641\u0642\u0637 \u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u0634\u0631\u0648\u0637 \u0627\u0644\u062A\u064A \u062A\u0623\u062A\u064A \u0645\u0639 \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062A \u0642\u0628\u0644 \u0642\u0628\u0648\u0644\u0647\u0627.</p>
  <p>\u0644\u0646\u0641\u062A\u0631\u0636 \u0623\u0646\u0643 \u0633\u062A\u0648\u062F\u0639 \u0628\u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629. \u0641\u064A \u0647\u0630\u0647 \u0627\u0644\u062D\u0627\u0644\u0629\u060C \u062A\u062E\u0628\u0631\u0646\u0627 \u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u0623\u0646 \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062A \u0628\u0633\u064A\u0637\u0629 \u0648\u0644\u0643\u0646\u0647\u0627 \u0644\u064A\u0633\u062A \u0633\u064A\u0626\u0629 \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0645\u0627 \u062A\u062D\u0635\u0644 \u0639\u0644\u064A\u0647. \u0625\u0630\u0627 \u0643\u0646\u062A \u0644\u0627\u0639\u0628\u064B\u0627 \u0644\u0623\u0648\u0644 \u0645\u0631\u0629 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u060C \u0641\u0633\u062A\u062C\u062F \u062D\u0632\u0645\u0629 \u062A\u0631\u062D\u064A\u0628 \u0641\u064A \u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646. \u0647\u0630\u0647 \u0647\u064A \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062A\u064A \u0633\u062A\u0628\u062F\u0623 \u0631\u062D\u0644\u062A\u0643 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u060C \u0648\u0633\u062A\u0633\u0627\u0639\u062F\u0643 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0632 \u0628\u0627\u0644\u062C\u0627\u0626\u0632\u0629 \u0627\u0644\u0643\u0628\u0631\u0649.</p>
  <p>\u0625\u0646\u0647\u0627 \u0644\u064A\u0633\u062A \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062A\u0631\u062D\u064A\u0628\u064A\u0629 \u0645\u062A\u0627\u062D\u0629 \u0641\u0642\u0637. \u0628\u0639\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062A\u0631\u062D\u064A\u0628\u064A\u0629\u060C \u0639\u0644\u064A\u0643 \u0627\u0644\u0627\u0646\u062A\u0628\u0627\u0647 \u0625\u0644\u0649 \u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u0625\u064A\u062F\u0627\u0639. \u0647\u0630\u0647 \u0647\u064A \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u062F\u0645\u0647\u0627 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0623\u062D\u064A\u0627\u0646\u064B\u0627 \u0639\u0644\u0649 \u0625\u064A\u062F\u0627\u0639 \u0639\u0634\u0648\u0627\u0626\u064A \u062A\u062D\u062F\u062F\u0647 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0644\u0639\u0628. \u0648\u0625\u0630\u0627 \u0643\u0646\u062A \u0645\u062D\u0638\u0648\u0638\u064B\u0627\u060C \u0641\u0633\u062A\u062C\u0644\u0628 \u0645\u0639\u0647\u0627 \u062C\u0648\u0627\u0626\u0632 \u0643\u0628\u0631\u0649 \u0623\u0648 \u0635\u063A\u064A\u0631\u0629.</p>
  <p>\u062A\u0645\u0627\u0645\u064B\u0627 \u0643\u0645\u0627 \u0647\u0648 \u0627\u0644\u062D\u0627\u0644 \u0639\u0646\u062F\u0645\u0627 \u062A\u062D\u062F\u062F \u0625\u064A\u062F\u0627\u0639\u064B\u0627 \u0639\u0627\u062F\u064A\u0627 \u060C \u0641\u0625\u0646\u0643 \u062A\u0637\u0627\u0644\u0628 \u0628\u0645\u0643\u0627\u0641\u0623\u062A\u0643 \u0641\u064A \u0623\u0645\u064A\u0646 \u0627\u0644\u0635\u0646\u062F\u0648\u0642 \u0639\u0646\u062F\u0645\u0627 \u062A\u0636\u0639 \u0625\u064A\u062F\u0627\u0639\u064B\u0627 \u0628\u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648. \u0648\u062A\u0630\u0643\u0631 \u0623\u0646\u0647 \u0644\u0627 \u064A\u0645\u0643\u0646 \u0644\u0623\u062D\u062F \u0625\u062C\u0628\u0627\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629. \u0627\u0644\u062E\u064A\u0627\u0631 \u0644\u0643. \u0625\u0646\u0647 \u062E\u064A\u0627\u0631 \u064A\u062C\u0628 \u0639\u0644\u064A\u0643 \u0627\u062A\u062E\u0627\u0630\u0647 \u0628\u0639\u062F \u0627\u0644\u0627\u0637\u0644\u0627\u0639 \u0639\u0644\u0649 \u062C\u0645\u064A\u0639 \u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u0627\u0644\u0623\u062D\u0643\u0627\u0645 \u0627\u0644\u062A\u064A \u062A\u0623\u062A\u064A \u0645\u0639 \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629. \u062A\u0630\u0643\u0631, \u0627\u0644\u0631\u0647\u0627\u0646 \u064A\u062C\u0628 \u0627\u0633\u062A\u064A\u0641\u0627\u0621 \u0627\u0644\u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0642\u0628\u0644 \u0623\u0646 \u062A\u062A\u0645\u0643\u0646 \u0645\u0646 \u0633\u062D\u0628 \u0623\u064A \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0633\u0628 \u0627\u0644\u062A\u064A \u062A\u0643\u0648\u0646 \u0645\u062D\u0638\u0648\u0638\u064B\u0627 \u0628\u0645\u0627 \u064A\u0643\u0641\u064A \u0644\u0644\u0641\u0648\u0632 \u0628\u0647\u0627. \u062A\u0630\u0643\u0631 \u0623\u064A\u0636\u064B\u0627 \u0623\u0646\u0647 \u0639\u0644\u0649 \u0627\u0644\u0631\u063A\u0645 \u0645\u0646 \u0648\u062C\u0648\u062F \u0641\u0631\u0635\u0629 \u0644\u0631\u0628\u062D \u0627\u0644\u0643\u062B\u064A\u0631 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u060C \u0639\u0644\u064A\u0643 \u0623\u0646 \u062A\u062A\u0630\u0643\u0631 \u0623\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0645\u062E\u0635\u0635\u0629 \u0644\u0644\u062A\u0631\u0641\u064A\u0647 \u0641\u0642\u0637.</p>
  
  <h2>\u0643\u064A\u0641\u064A\u0629 \u0627\u062E\u062A\u064A\u0627\u0631 \u0643\u0627\u0632\u064A\u0646\u0648 \u0628\u062A\u0643\u0648\u064A\u0646 \u0627\u0644\u0645\u0646\u0627\u0633\u0628</h2>
  <p>\u0646\u0631\u064A\u062F \u062C\u0645\u064A\u0639\u064B\u0627 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u062E\u0650\u064A\u0627\u0631 \u0627\u0644\u0623\u0641\u0636\u0644 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631\u060C \u0648\u0646\u0631\u064A\u062F \u0627\u0644\u0641\u0648\u0632 \u0628\u0627\u0644\u062C\u0627\u0626\u0632\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0641\u064A \u0627\u0644\u062C\u0648\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\u060C \u0648\u0646\u0631\u064A\u062F \u0627\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u064A\u0647\u0627 \u062C\u0645\u064A\u0639\u064B\u0627\u060C \u0648\u0646\u0631\u064A\u062F\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631. \u0644\u0633\u0648\u0621 \u0627\u0644\u062D\u0638\u060C \u0647\u0630\u0627 \u0644\u064A\u0633 \u0648\u0627\u0642\u0639\u064A\u0627. \u0646\u062D\u0646 \u0646\u062A\u0639\u0644\u0645.</p>
  <p>\u0644\u0627 \u062A\u0648\u062C\u062F \u062E\u0631\u064A\u0637\u0629 \u0637\u0631\u064A\u0642 \u0633\u0631\u064A\u0629 \u0644\u0644\u062F\u0641\u0639\u0627\u062A \u0627\u0644\u0636\u062E\u0645\u0629 \u0648\u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u062B\u0627\u0644\u064A \u0641\u064A \u0627\u0644\u062C\u0648\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\u060C \u062D\u062A\u0649 \u0639\u0646\u062F\u0645\u0627 \u064A\u062A\u0639\u0644\u0642 \u0627\u0644\u0623\u0645\u0631 \u0628\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 - \u0648\u0644\u0643\u0646 \u0625\u0644\u064A\u0643 \u0628\u0639\u0636 \u0627\u0644\u0646\u0635\u0627\u0626\u062D:</p>
  <ul>
    <li>\u062A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u0625\u0644\u0642\u0627\u0621 \u0646\u0638\u0631\u0629 \u0639\u0644\u0649 \u0646\u0648\u0639 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062A\u064A \u064A\u0642\u062F\u0645\u0647\u0627 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0625\u0630\u0627 \u0644\u0645 \u064A\u0643\u0646 \u0644\u062F\u064A\u0647\u0645 \u0623\u064A \u0623\u0644\u0639\u0627\u0628 \u062A\u062D\u0628\u0647\u0627 \u0623\u0648 \u0623\u064A \u0623\u0644\u0639\u0627\u0628 \u062A\u0631\u063A\u0628 \u0641\u064A \u062A\u062C\u0631\u0628\u062A\u0647\u0627.</li>
    <li>\u0644\u0646\u0641\u062A\u0631\u0636 \u0623\u0646 \u0644\u062F\u064A\u0643 \u0646\u0648\u0639\u064B\u0627 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0648\u0644\u064A\u0633 \u062C\u0645\u064A\u0639\u0647\u0627 \u0623\u0648 \u0644\u0627 \u062A\u0631\u064A\u062F \u062A\u062C\u0631\u0650\u0628\u0629 \u0639\u0645\u0644\u0629 \u0645\u062E\u062A\u0644\u0641\u0629 \u0639\u0646 \u062A\u0644\u0643 \u0627\u0644\u062A\u064A \u062A\u0639\u0631\u0641\u0647\u0627. \u0641\u064A \u0647\u0630\u0647 \u0627\u0644\u062D\u0627\u0644\u0629\u060C \u064A\u062C\u0628 \u0639\u0644\u064A\u0643 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0637\u0631\u0642 \u0627\u0644\u062F\u0641\u0639 \u0644\u0644\u062A\u0623\u0643\u062F \u0645\u0646 \u0623\u0646 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u062A\u0642\u0628\u0644 \u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0643\u0637\u0631\u064A\u0642\u0629 \u062F\u0641\u0639 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u062E\u0627\u0635 \u0628\u0647\u0645.</li>
    <li>\u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 - \u0646\u0639\u0644\u0645 \u0623\u0646\u0646\u0627 \u062A\u062D\u062F\u062B\u0646\u0627 \u0628\u0627\u0644\u0641\u0639\u0644 \u0639\u0646 \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u0645\u0647\u0645\u0629\u060C \u0644\u0643\u0646\u0646\u0627 \u0633\u0646\u0643\u0631\u0631\u0647\u0627. \u0646\u062D\u0646 \u0646\u0639\u0644\u0645 \u0623\u0646 \u0627\u0644\u0639\u062F\u064A\u062F \u0645\u0646 \u0627\u0644\u0644\u0627\u0639\u0628\u064A\u0646 \u064A\u0647\u062A\u0645\u0648\u0646 \u0641\u0642\u0637 \u0628\u0646\u0648\u0639 \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062A\u064A \u064A\u0642\u062F\u0645\u0647\u0627 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0644\u0644\u0627\u0639\u0628\u064A\u0646 \u0627\u0644\u062C\u062F\u062F \u0648\u0627\u0644\u0642\u062F\u0627\u0645\u0649.</li>
    <li>\u062A\u0623\u0643\u062F \u0645\u0646 \u0623\u0646\u0647 \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0644\u0639\u0628 - \u062A\u062D\u062A\u0648\u064A \u0645\u0639\u0638\u0645 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0642\u0627\u0626\u0645\u0629 \u0628\u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0645\u062D\u0638\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u0644\u0627 \u064A\u0645\u0643\u0646\u0647\u0627 \u0627\u0644\u0644\u0639\u0628 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u062E\u0627\u0635 \u0628\u0647\u0627. \u062A\u0623\u0643\u062F \u0645\u0646 \u0623\u0646 \u0628\u0644\u062F\u0643 \u0644\u064A\u0633 \u0639\u0644\u0649 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0642\u064A\u062F\u0629.</li>
  </ul>
  
  <h2>\u0647\u0644 \u0645\u0646 \u0627\u0644\u0635\u0639\u0628 \u0627\u0644\u0625\u064A\u062F\u0627\u0639 \u0623\u0648 \u0627\u0644\u0633\u062D\u0628\u061F</h2>
  <p>\u064A\u0635\u0639\u0628 \u0641\u0647\u0645 \u0627\u0644\u0639\u062F\u064A\u062F \u0645\u0646 \u0637\u0631\u0642 \u0627\u0644\u062F\u0641\u0639\u060C \u0648\u062A\u0643\u0645\u0646 \u0646\u0642\u0637\u0629 \u0628\u064A\u0639 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0641\u064A \u0623\u0646\u0647 \u0645\u0646 \u0627\u0644\u0645\u0641\u062A\u0631\u0636 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0643\u0644 \u0634\u064A\u0621 \u0623\u0633\u0647\u0644 \u0639\u0646\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647 - \u0641\u0647\u0644 \u0647\u0630\u0627 \u0623\u0633\u0647\u0644\u061F</p>
  <p>\u0646\u0639\u0645 \u060C \u0627\u0644\u0623\u0645\u0631 \u0633\u0647\u0644 \u0645\u062B\u0644 \u0633\u0631\u0642\u0629 \u0627\u0644\u062D\u0644\u0648\u0649 \u0645\u0646 \u0637\u0641\u0644. \u0644\u0627 \u064A\u0648\u062C\u062F \u0633\u0648\u0649 \u0628\u0636\u0639 \u062E\u0637\u0648\u0627\u062A \u0644\u0644\u0625\u064A\u062F\u0627\u0639 \u0648\u062E\u0637\u0648\u0627\u062A \u0642\u0644\u064A\u0644\u0629 \u0641\u0642\u0637 \u0644\u0625\u062C\u0631\u0627\u0621 \u0627\u0644\u0633\u062D\u0628. \u0648\u0628\u0627\u0644\u0637\u0628\u0639\u060C \u0646\u062D\u0646 \u0647\u0646\u0627 \u0644\u0646\u062E\u0628\u0631\u0643 \u0628\u0643\u064A\u0641\u064A\u0629 \u0627\u0644\u0642\u064A\u0627\u0645 \u0628\u0630\u0644\u0643:</p>
  <p>\u0647\u0630\u0647 \u0647\u064A \u0627\u0644\u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u0648\u0645 \u0628\u0647\u0627 \u0628\u0627\u0644\u0625\u064A\u062F\u0627\u0639 \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0623\u0648 \u0623\u064A \u0639\u0645\u0644\u0629 \u0645\u0634\u0641\u0631\u0629 \u0623\u062E\u0631\u0649:</p>
  <ul>
    <li>\u0623\u0648\u0644\u0627\u064B\u060C \u0639\u0644\u064A\u0643 \u0623\u0646 \u062A\u062C\u062F \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u0641\u0636\u0644 \u0644\u062F\u064A\u0643 \u0627\u0644\u0630\u064A \u064A\u0642\u0628\u0644 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0643\u062E\u064A\u0627\u0631 \u0644\u0644\u062F\u0641\u0639 \u0648\u062A\u0634\u0642 \u0637\u0631\u064A\u0642\u0643 \u0625\u0644\u0649 \u0623\u0645\u064A\u0646 \u0627\u0644\u0635\u0646\u062F\u0648\u0642.</li>
    <li>\u0627\u062E\u062A\u0631 \u0645\u0627 \u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0631\u064A\u062F \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0639\u0645\u0644\u0629 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0623\u0648 \u0646\u0648\u0639 \u0645\u062E\u062A\u0644\u0641 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0634\u0641\u0631\u0629.</li>
    <li>\u0648\u0628\u0639\u062F \u0630\u0644\u0643 \u0643\u0644 \u0645\u0627 \u062A\u0628\u0642\u0649 \u0647\u0648 \u0643\u062A\u0627\u0628\u0629 \u0627\u0644\u0645\u0628\u0644\u063A \u0627\u0644\u0630\u064A \u062A\u0631\u063A\u0628 \u0641\u064A \u0625\u064A\u062F\u0627\u0639\u0647 \u0648\u0627\u0644\u0646\u0642\u0631 \u0641\u0648\u0642 \u0625\u062F\u062E\u0627\u0644. \u0648\u0641\u064A \u063A\u0636\u0648\u0646 \u0644\u062D\u0638\u0627\u062A \u0642\u0644\u064A\u0644\u0629 \u060C \u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0627\u0644\u0631\u0635\u064A\u062F \u0641\u064A \u062D\u0633\u0627\u0628 \u0627\u0644\u0644\u0627\u0639\u0628 \u0627\u0644\u062E\u0627\u0635 \u0628\u0643.</li>
  </ul>
  <p>\u0647\u0630\u0647 \u0647\u064A \u0627\u0644\u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u0648\u0645 \u0628\u0647\u0627 \u0628\u0633\u062D\u0628 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0639\u0646\u062F\u0645\u0627 \u062A\u0643\u0648\u0646 \u0645\u062D\u0638\u0648\u0638\u064B\u0627 \u0628\u0645\u0627 \u064A\u0643\u0641\u064A \u0644\u0644\u0641\u0648\u0632:</p>
  <ul>
    <li>\u0623\u0648\u0644 \u0634\u064A\u0621 \u0639\u0644\u064A\u0643 \u0627\u0644\u0642\u064A\u0627\u0645 \u0628\u0647 \u0647\u0648 \u0627\u0644\u0630\u0647\u0627\u0628 \u0625\u0644\u0649 \u0623\u0645\u064A\u0646 \u0627\u0644\u0635\u0646\u062F\u0648\u0642 \u0648\u0627\u062E\u062A\u064A\u0627\u0631 \u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u0633\u062D\u0628 \u0627\u0644\u062A\u064A \u062A\u0641\u0636\u0644 \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647\u0627</li>
    <li>\u0623\u062F\u062E\u0644 \u0627\u0644\u0645\u0628\u0644\u063A \u0627\u0644\u0630\u064A \u062A\u0631\u063A\u0628 \u0641\u064A \u0633\u062D\u0628\u0647 \u060C \u062B\u0645 \u0627\u0636\u063A\u0637 \u0639\u0644\u0649 \u062A\u0623\u0643\u064A\u062F</li>
  </ul>
  <p>\u0643\u0645\u0627 \u062A\u0631\u0649\u060C \u0647\u0630\u0627 \u0623\u0633\u0647\u0644 \u0628\u0643\u062B\u064A\u0631 \u0645\u0645\u0627 \u0633\u064A\u0643\u0648\u0646 \u0639\u0644\u064A\u0647 \u0645\u0639 \u0627\u0644\u0639\u062F\u064A\u062F \u0645\u0646 \u062E\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u0623\u062E\u0631\u0649 \u0627\u0644\u062A\u064A \u062A\u062C\u062F\u0647\u0627 \u0641\u064A \u0643\u0627\u0632\u064A\u0646\u0648 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A - \u0648\u0644\u0643\u0646 \u0643\u0645\u0627 \u0646\u0639\u0644\u0645 \u062C\u0645\u064A\u0639\u064B\u0627 \u060C \u0647\u0630\u0627 \u0644\u064A\u0633 \u0634\u064A\u0626\u064B\u0627 \u0646\u0631\u0627\u0647 \u0641\u064A \u0643\u0644 \u0645\u0643\u0627\u0646.</p>

  <h2>\u0645\u0627 \u0647\u064A \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0623\u0646 \u062A\u062C\u062F\u0647\u0627 \u0641\u064A \u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648\u061F</h2>
  <p>\u0645\u0627 \u064A\u062C\u0639\u0644 \u0623\u0641\u0636\u0644 \u062A\u062C\u0631\u0628\u0629 \u0644\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0647\u0648 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u064A\u0647\u0627 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648. \u064A\u062D\u062A\u0627\u062C \u0627\u0644\u0644\u0627\u0639\u0628 \u0625\u0644\u0649 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0642\u0627\u062F\u0631\u064B\u0627 \u0639\u0644\u0649 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0639\u062F\u062F \u0627\u0644\u0628\u0639\u0636 \u0644\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u0645\u0646 \u0628\u064A\u0646\u0647\u0627\u060C \u0648\u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0646\u0648\u0639\u064B\u0627 \u0645\u0646 \u0627\u0644\u062A\u0648\u0627\u0632\u0646 \u0644\u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u0633\u0648\u0642 \u0645\u0641\u062A\u0648\u062D\u064B\u0627 \u0644\u0623\u0643\u062B\u0631 \u0645\u0646 \u0646\u0648\u0639 \u0648\u0627\u062D\u062F \u0645\u0646 \u0627\u0644\u0644\u0627\u0639\u0628\u064A\u0646.</p>
  <p>\u062A\u0639\u062A\u0628\u0631 \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0647\u064A \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0628\u064A\u0646 \u0627\u0644\u0644\u0627\u0639\u0628\u064A\u0646 \u0641\u064A \u0627\u0644\u0633\u0648\u0642 \u0628\u0634\u0643\u0644 \u0645\u0637\u0644\u0642\u060C \u0648\u062F\u0639\u0646\u0627 \u0646\u062E\u0628\u0631\u0643 \u0642\u0644\u064A\u0644\u0627\u064B \u0639\u0645\u0627 \u064A\u0645\u0643\u0646\u0643 \u062A\u0648\u0642\u0639\u0647 \u0645\u0646 \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0639\u0644\u0649 \u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0628\u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648.</p>
  <p>\u0633\u062A\u0643\u0648\u0646 \u0623\u064A \u0644\u064F\u0639\u0652\u0628\u064E\u0629 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0642\u0645\u0627\u0631 \u0639\u0634\u0648\u0627\u0626\u064A\u0629 \u062A\u0645\u0627\u0645\u064B\u0627\u060C \u062A\u0645\u0627\u0645\u064B\u0627 \u0645\u062B\u0644 \u0631\u0645\u064A \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u0639\u062F\u0646\u064A\u0629. \u064A\u062E\u062A\u0627\u0631 \u0628\u0631\u0646\u0627\u0645\u062C \u0627\u0644\u062D\u0627\u0633\u0648\u0628 \u0627\u0644\u0630\u064A \u064A\u062A\u062D\u0643\u0645 \u0641\u064A \u0627\u0644\u0644\u0639\u0628\u0629 \u0631\u0645\u0632\u064B\u0627 \u0639\u0634\u0648\u0627\u0626\u064A\u064B\u0627 \u0641\u064A \u0627\u0644\u0635\u0641 \u0627\u0644\u0623\u0648\u0644\u060C \u062B\u0645 \u0627\u0644\u062B\u0627\u0646\u064A. \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0647\u0648 \u0627\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0626\u0648\u064A\u0629 \u0644\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0645\u062F\u0641\u0648\u0639\u0629 \u0644\u0644\u0627\u0639\u0628 \u0641\u064A \u0627\u0644\u0645\u062A\u0648\u0633\u0637. \u0643\u0644 \u062F\u0648\u0631\u0629 \u0641\u064A \u0627\u0644\u0644\u0639\u0628\u0629 \u0644\u0647\u0627 \u0646\u0641\u0633 \u0641\u0631\u0635\u0629 \u0627\u0644\u0641\u0648\u0632 \u0623\u0648 \u0627\u0644\u062E\u0633\u0627\u0631\u0629 \u0645\u062B\u0644 \u0627\u0644\u0644\u0639\u0628\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u061B \u0644\u0646 \u062A\u0642\u0648\u0644 \u0639\u0646 \u0627\u0644\u0645\u062F\u0629 \u0645\u0646\u0630 \u0623\u0646 \u062A\u0645 \u062F\u0641\u0639 \u0622\u062E\u0631 \u062C\u0627\u0626\u0632\u0629 \u0643\u0628\u0631\u0649 \u0623\u0648 \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0645\u064E\u0643\u0650\u0646\u064E\u0629 \u0627\u0644\u0642\u0645\u0627\u0631 "\u0633\u0627\u062E\u0646\u0629" \u0623\u0648 "\u0628\u0627\u0631\u062F\u0629"</p>
  <p>\u0641\u064A \u0627\u0644\u062B\u0645\u0627\u0646\u064A\u0646\u064A\u0627\u062A\u060C \u0623\u0635\u0628\u062D\u062A \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631 \u062A\u062D\u0638\u0649 \u0628\u0634\u0639\u0628\u064A\u0629 \u0643\u0628\u064A\u0631\u0629 \u0648\u062A\u062C\u0627\u0648\u0632\u062A \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0645\u062B\u0644 \u0627\u0644\u0643\u0631\u0627\u0628\u0633 \u0648\u0627\u0644\u0628\u0644\u0627\u0643 \u062C\u0627\u0643. \u062A\u0634\u0643\u0644 \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631 \u0648\u0644\u0639\u0628\u0629 \u0627\u0644\u0641\u064A\u062F\u064A\u0648 \u0628\u0648\u0643\u0631 \u0627\u0644\u0622\u0646 \u0623\u0643\u062B\u0631 \u0645\u0646 70 \u0628\u0627\u0644\u0645\u0627\u0626\u0629 \u0645\u0646 \u0623\u0631\u0628\u0627\u062D \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A. \u0627\u0644\u0622\u0646 \u0628\u0639\u062F \u0623\u0646 \u062F\u062E\u0644\u0646\u0627 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u060C \u062A\u0648\u0627\u0635\u0644 \u062C\u0646\u064A \u0627\u0644\u0623\u0631\u0628\u0627\u062D \u0645\u0646 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u0648\u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0648\u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0642\u0628\u0644 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648. \u0647\u0630\u0627 \u0644\u0633\u0628\u0628 \u0628\u0633\u064A\u0637: \u0627\u0644\u062C\u0648\u0627\u0626\u0632 \u0627\u0644\u0643\u0628\u0631\u0649. \u0639\u0646\u062F\u0645\u0627 \u062A\u0645\u062A \u0631\u0642\u0645\u0646\u0629 \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631\u060C \u0623\u0635\u0628\u062D \u0645\u0646 \u0627\u0644\u0645\u0645\u0643\u0646 \u062C\u0639\u0644 \u0627\u0644\u0641\u0648\u0632 \u0628\u0627\u0644\u062C\u0627\u0626\u0632\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0623\u0642\u0644 \u062A\u0643\u0631\u0627\u0631\u064B\u0627\u060C \u0645\u0645\u0627 \u064A\u0639\u0646\u064A \u0623\u064A\u0636\u064B\u0627 \u0623\u0646 \u0627\u0644\u0641\u0648\u0632 \u0628\u0627\u0644\u062C\u0627\u0626\u0632\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0639\u0644\u0649 \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0623\u0635\u0628\u062D \u0623\u0643\u0628\u0631 \u0639\u0646\u062F\u0645\u0627 \u0641\u0632\u062A \u0628\u0647\u0627 \u0644\u0623\u0648\u0644 \u0645\u0631\u0629. \u0648\u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u064A\u062D\u0628\u0648\u0646 \u0627\u0644\u062C\u0648\u0627\u0626\u0632 \u0627\u0644\u0643\u0628\u064A\u0631\u0629! \u0625\u0630\u0627 \u0644\u0639\u0628\u062A \u0645\u0642\u0627\u0628\u0644 5 \u062F\u0648\u0644\u0627\u0631\u0627\u062A \u0639\u0644\u0649 \u0637\u0627\u0648\u0644\u0629 \u0627\u0644\u0628\u0644\u0627\u0643 \u062C\u0627\u0643\u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0641\u0648\u0632 \u0628\u062D\u062F \u0623\u0642\u0635\u0649 7.5 \u062F\u0648\u0644\u0627\u0631\u0627\u062A\u060C \u0648\u0644\u0643\u0646 \u0625\u0630\u0627 \u0644\u0639\u0628\u062A \u0628\u062B\u0644\u0627\u062B\u0629 \u062F\u0648\u0644\u0627\u0631\u0627\u062A \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0642\u0645\u0627\u0631\u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0641\u0648\u0632 \u0628\u0639\u062F\u0629 \u0622\u0644\u0627\u0641 \u0623\u0648 \u0645\u0644\u0627\u064A\u064A\u0646 \u0627\u0644\u062F\u0648\u0644\u0627\u0631\u0627\u062A \u062F\u0641\u0639\u0629 \u0648\u0627\u062D\u062F\u0629\u060C \u0648\u0644\u0643\u0646 \u0647\u0630\u0627 \u0641\u0642\u0637 \u0625\u0630\u0627 \u0627\u0646\u062A \u0645\u062D\u0638\u0648\u0638. \u0648\u0644\u0643\u0646 \u0643\u0645\u0627 \u0642\u0644\u0646\u0627 \u0633\u0627\u0628\u0642\u0627\u060C \u064A\u062C\u0628 \u0627\u0644\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0643\u0623\u062F\u0627\u0629 \u062A\u0631\u0641\u064A\u0647 \u0648 \u0644\u064A\u0633 \u0645\u0635\u062F\u0631 \u0631\u0632\u0642.</p>
  <p>\u0648\u0644\u0643\u0646 \u0639\u0644\u0649 \u0627\u0644\u0631\u063A\u0645 \u0645\u0646 \u0634\u0639\u0628\u064A\u062A\u0647\u0627\u060C \u0625\u0644\u0627 \u0623\u0646 \u0647\u0646\u0627\u0643 \u062B\u0644\u0627\u062B \u0645\u0634\u0643\u0644\u0627\u062A \u0631\u0626\u064A\u0633\u064A\u0629 \u0641\u064A \u0644\u0639\u0628 \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631 \u0645\u0642\u0627\u0628\u0644 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629. \u0623\u0648\u0644\u0627\u064B \u0648\u0642\u0628\u0644 \u0643\u0644 \u0634\u064A\u0621\u060C \u0644\u0627 \u062A\u0643\u0648\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0634\u0641\u0627\u0641\u0629 \u062F\u0627\u0626\u0645\u064B\u0627 \u0628\u0634\u0623\u0646 \u0627\u0644\u0627\u062D\u062A\u0645\u0627\u0644\u0627\u062A \u0627\u0644\u062A\u064A \u062A\u0636\u0639\u0647\u0627 \u0641\u064A \u0643\u0644 \u0644\u0639\u0628\u0629\u060C \u0648\u0647\u0630\u0627 \u064A\u0639\u0646\u064A \u0623\u0646\u0647 \u0645\u0646 \u0627\u0644\u0635\u0639\u0628 \u0645\u0639\u0631\u0641\u0629 \u0645\u062F\u0649 \u0627\u062D\u062A\u0645\u0627\u0644\u064A\u0629 \u0627\u0644\u0641\u0648\u0632. \u062B\u0627\u0646\u064A\u064B\u0627 \u060C \u0628\u063A\u0636 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u0627\u062D\u062A\u0645\u0627\u0644\u0627\u062A \u0627\u0644\u0633\u0631\u064A\u0629 \u060C \u063A\u0627\u0644\u0628\u064B\u0627 \u0645\u0627 \u062A\u0643\u0648\u0646 \u062E\u0627\u0637\u0626\u0629 \u0648\u0623\u0633\u0648\u0623 \u0645\u0646 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0645\u062B\u0644 \u0627\u0644\u0643\u0631\u0627\u0628\u0633 \u0648\u0627\u0644\u0628\u0643\u0627\u0631\u0627\u062A \u0648\u0627\u0644\u0628\u0644\u0627\u0643 \u062C\u0627\u0643. \u062B\u0627\u0646\u064A\u064B\u0627\u060C \u0628\u063A\u0636 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u0627\u062D\u062A\u0645\u0627\u0644\u0627\u062A \u0627\u0644\u0633\u0631\u064A\u0629\u060C \u063A\u0627\u0644\u0628\u064B\u0627 \u0645\u0627 \u062A\u0643\u0648\u0646 \u062E\u0627\u0637\u0626\u0629 \u0648\u0623\u0633\u0648\u0623 \u0645\u0646 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0645\u062B\u0644 \u0627\u0644\u0643\u0631\u0627\u0628\u0633 \u0648\u0627\u0644\u0628\u0643\u0627\u0631\u0627\u062A \u0648\u0627\u0644\u0628\u0644\u0627\u0643 \u062C\u0627\u0643.</p>
  <p>\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0647\u064A \u0627\u0644\u0634\u064A\u0621 \u0627\u0644\u0643\u0628\u064A\u0631 \u0627\u0644\u062A\u0627\u0644\u064A \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A\u060C \u0644\u0630\u0644\u0643 \u062F\u0639\u0648\u0646\u0627 \u0646\u062A\u062D\u062F\u062B \u0639\u0646 \u0645\u0627 \u064A\u0645\u0643\u0646 \u0623\u0646 \u062A\u062A\u0648\u0642\u0639\u0647 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0645\u0646 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0648\u0646\u0645\u0646\u062D \u0627\u0644\u0645\u0628\u062A\u062F\u0626\u064A\u0646 \u0647\u0646\u0627\u0643 \u0641\u0631\u0635\u0629 \u0644\u0644\u062A\u0639\u0644\u0645 \u0628\u0633\u0631\u0639\u0629 \u0642\u0628\u0644 \u0623\u0646 \u064A\u0634\u062A\u0631\u0648\u0627 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0644\u0625\u0646\u0641\u0627\u0642 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0627\u0644\u062A\u064A \u062D\u0635\u0644\u0648\u0627 \u0639\u0644\u064A\u0647\u0627 \u0628\u0634\u0642 \u0627\u0644\u0623\u0646\u0641\u0633 \u0639\u0644\u0649 \u0645\u0627\u0643\u064A\u0646\u0627\u062A \u0627\u0644\u0642\u0645\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0648 \u0623\u0644\u0639\u0627\u0628 \u0623\u062E\u0631\u0649 \u0644\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0639\u0627\u0626\u062F \u0633\u0631\u064A\u0639.</p>
  <p>\u062A\u0642\u062F\u0645 \u0645\u0639\u0638\u0645 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629\u060C \u0648\u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0644\u0639\u0628 \u0641\u064A \u0643\u0627\u0632\u064A\u0646\u0648 \u0644\u0627 \u064A\u062A\u0648\u0641\u0631 \u0628\u0647\u0627\u060C \u0641\u0639\u0644\u064A\u0643 \u0627\u0644\u062A\u0641\u0643\u064A\u0631 \u0641\u064A \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0643\u0627\u0632\u064A\u0646\u0648 \u0622\u062E\u0631 \u064A\u0642\u062F\u0645 \u0647\u0630\u0627.</p>
  <p>\u0644\u064A\u0633 \u0639\u0644\u064A\u0643 \u0627\u0644\u0644\u0639\u0628 \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u0645\u0627\u0644 \u0644\u0644\u0639\u0628 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0637\u0627\u0648\u0644\u0629. \u062A\u0642\u062F\u0645 \u0627\u0644\u0639\u062F\u064A\u062F \u0645\u0646 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0644\u0639\u0628 \u0627\u0644\u0645\u062C\u0627\u0646\u064A \u0623\u0648 \u0627\u0644\u0644\u0639\u0628 \u0627\u0644\u062A\u062C\u0631\u064A\u0628\u064A \u060C \u0644\u0630\u0644\u0643 \u0644\u0627 \u062A\u0642\u0648\u0645 \u0628\u0625\u064A\u062F\u0627\u0639 \u0623\u0645\u0648\u0627\u0644 \u062D\u0642\u064A\u0642\u064A\u0629. \u0639\u0644\u0649 \u0627\u0644\u0645\u062F\u0649 \u0627\u0644\u0637\u0648\u064A\u0644\u060C \u0642\u062F \u064A\u0635\u0628\u062D \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0645\u0645\u0644\u064B\u0627 \u0628\u0639\u0636 \u0627\u0644\u0634\u064A\u0621\u060C \u0648\u0644\u0643\u0646 \u0647\u0646\u0627\u0643 \u0641\u0631\u0635 \u0643\u0627\u0645\u0644\u0629 \u0644\u0625\u064A\u062F\u0627\u0639 \u0627\u0644\u0646\u0642\u0648\u062F \u0641\u064A \u0648\u0642\u062A \u0644\u0627\u062D\u0642.</p>
  <p>\u0625\u0646 \u0627\u0644\u0645\u0628\u0644\u063A \u0627\u0644\u0630\u064A \u062A\u0631\u0627\u0647\u0646 \u0628\u0647 \u0639\u0644\u0649 \u0644\u064F\u0639\u0652\u0628\u064E\u0629 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0645\u062A\u0631\u0648\u0643 \u0644\u0643 \u060C \u0648\u0644\u0643\u0646 \u063A\u0627\u0644\u0628\u064B\u0627 \u0645\u0627 \u064A\u0643\u0648\u0646 \u0647\u0646\u0627\u0643 \u062D\u062F \u0627\u0644\u0623\u062F\u0646\u0649 \u0645\u0646 \u0627\u0644\u0631\u0647\u0627\u0646 \u0644\u0644\u0645\u0634\u0627\u0631\u0643\u0629. \u064A\u062E\u062A\u0644\u0641 \u0647\u0630\u0627 \u0628\u0627\u062E\u062A\u0644\u0627\u0641 \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u060C \u0644\u0630\u0627 \u0644\u0627 \u062A\u062A\u0631\u062F\u062F \u0641\u064A \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0646\u0641\u0633\u0643 \u0639\u0646\u062F\u0645\u0627 \u062A\u062C\u062F \u0643\u0627\u0632\u064A\u0646\u0648 \u0633\u062A\u0644\u0639\u0628 \u0641\u064A\u0647.</p>
  <p>\u0644\u0639\u0628\u0629 \u0627\u0644\u0648\u0631\u0642 \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A\u060C \u0648\u062A\u0633\u0645\u0649 \u0623\u064A\u0636\u064B\u0627 \u0631\u0642\u0645 \u0648\u0627\u062D\u062F \u0648\u0639\u0634\u0631\u064A\u0646\u060C \u0647\u064A \u0644\u0639\u0628\u0629 \u0637\u0627\u0648\u0644\u0629 \u064A\u0631\u0628\u0637\u0647\u0627 \u0645\u0639\u0638\u0645 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648. \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u062D\u0627\u0636\u0631 \u060C \u064A\u0645\u0643\u0646\u0643 \u0644\u0639\u0628 \u0627\u0644\u0628\u0644\u0627\u0643 \u062C\u0627\u0643 \u0641\u064A \u0627\u0644\u0645\u0646\u0632\u0644 \u0641\u064A \u063A\u0631\u0641\u0629 \u0627\u0644\u0645\u0639\u064A\u0634\u0629 \u060C \u0637\u0627\u0644\u0645\u0627 \u0623\u0646\u0643 \u0645\u062A\u0635\u0644 \u0628\u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0648\u062A\u0642\u0648\u0645 \u0628\u0625\u064A\u062F\u0627\u0639 \u0645\u0628\u0644\u063A \u0641\u064A \u0643\u0627\u0632\u064A\u0646\u0648. \u062C\u0645\u064A\u0639 \u0645\u0632\u0648\u062F\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u064A\u0646 \u0644\u062F\u064A\u0647\u0645 \u0628\u0644\u0627\u0643 \u062C\u0627\u0643 \u0641\u064A \u0645\u062D\u0627\u0641\u0638\u0647\u0645.</p>
  <p>\u0627\u0644\u0628\u0648\u0643\u0631 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0647\u064A \u0644\u0639\u0628\u0629 \u0648\u0631\u0642 \u0645\u062B\u064A\u0631\u0629 \u062A\u0646\u0627\u0633\u0628 \u0645\u0639\u0638\u0645 \u0627\u0644\u0646\u0627\u0633. \u064A\u0633\u062A\u063A\u0631\u0642 \u0627\u0644\u0623\u0645\u0631 \u0648\u0642\u062A\u064B\u0627 \u0644\u062A\u0635\u0628\u062D \u062C\u064A\u062F\u064B\u0627 \u0641\u064A \u0627\u0644\u0628\u0648\u0643\u0631 \u060C \u0648\u0643\u0627\u0646 \u0647\u0646\u0627\u0643 \u0627\u0644\u0643\u062B\u064A\u0631 \u0645\u0646 \u0627\u0644\u0646\u0642\u0627\u0634 \u062D\u0648\u0644 \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0644\u0639\u0628\u0629 \u0627\u0644\u0628\u0648\u0643\u0631 \u0647\u064A \u0644\u0639\u0628\u0629 \u0645\u0647\u0627\u0631\u0629. \u0647\u0646\u0627\u060C \u0647\u0646\u0627\u0643 \u0622\u0631\u0627\u0621 \u0645\u062A\u0636\u0627\u0631\u0628\u0629 \u0645\u0646 \u0635\u0646\u0627\u0639 \u0627\u0644\u0628\u0648\u0643\u0631 \u0648\u0627\u0644\u0633\u0644\u0637\u0627\u062A. \u0645\u0646 \u062C\u0627\u0646\u0628\u0647\u0627\u060C \u064A\u0639\u062A\u0642\u062F \u0635\u0646\u0627\u0639 \u0627\u0644\u0628\u0648\u0643\u0631 \u0623\u0646\u0647\u0627 \u0644\u0639\u0628\u0629 \u0645\u0647\u0627\u0631\u0629. \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0646\u0641\u0633\u0647\u060C \u062A\u0639\u062A\u0628\u0631 \u0627\u0644\u0633\u0644\u0637\u0627\u062A \u0627\u0644\u0628\u0648\u0643\u0631 \u0644\u0639\u0628\u0629 \u0628\u0645\u0648\u062C\u0628 \u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u064A\u0627\u0646\u0635\u064A\u0628 \u0648\u0647\u064A \u062A\u062A\u0639\u0644\u0642 \u0628\u0627\u0644\u062D\u0638 \u0623\u0643\u062B\u0631 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u0631\u0629.</p>
  <p>\u0643\u0627\u0646\u062A \u0644\u0639\u0628\u0629 \u0641\u064A\u062F\u064A\u0648 \u0628\u0648\u0643\u0631 \u0631\u0642\u0645\u064A\u0629 \u0641\u064A \u0648\u0642\u062A \u0645\u0628\u0643\u0631 \u060C \u0644\u0630\u0627 \u0643\u0627\u0646\u062A \u0648\u0627\u062D\u062F\u0629 \u0645\u0646 \u0623\u0648\u0644\u0649 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0644\u0639\u0628\u0647\u0627 \u062F\u0648\u0646 \u0627\u0644\u062D\u0627\u062C\u0629 \u0625\u0644\u0649 \u062D\u0645\u0644 \u0623\u0648\u0631\u0627\u0642 \u0641\u064A \u064A\u062F\u0643. \u062A\u0639\u062A\u0645\u062F \u0644\u0639\u0628\u0629 \u0628\u0648\u0643\u0631 \u0627\u0644\u0641\u064A\u062F\u064A\u0648 \u062F\u0627\u0626\u0645\u064B\u0627 \u0639\u0644\u0649 \u0644\u0639\u0628\u0629 \u0627\u0644\u0628\u0648\u0643\u0631 \u0627\u0644\u0639\u0627\u062F\u064A\u0629 \u060C \u062D\u064A\u062B \u062A\u0644\u0639\u0628 \u0628\u0623\u0639\u0644\u0649 \u062E\u0645\u0633 \u0623\u0648\u0631\u0627\u0642 \u0641\u064A \u064A\u062F\u0643.</p>
  <p>\u0627\u0644\u0631\u0627\u0641\u0639\u0627\u062A \u060C \u0623\u0648 \u0627\u0644\u0623\u0641\u0636\u0644 \u060C \u0647\u064A \u0634\u0643\u0644 \u0634\u0627\u0626\u0639 \u0645\u0646 \u0628\u0648\u0643\u0631 \u0627\u0644\u0641\u064A\u062F\u064A\u0648. \u0647\u0646\u0627 \u062A\u0643\u0633\u0628 \u0627\u0644\u0645\u0627\u0644 \u0628\u0645\u062C\u0631\u062F \u0623\u0646 \u064A\u0643\u0648\u0646 \u0644\u062F\u064A\u0643 \u0632\u0648\u062C \u0645\u0646 \u0627\u0644\u0631\u0627\u0641\u0639\u0627\u062A \u0623\u0648 \u0623\u0641\u0636\u0644.</p>
  <p>\u0641\u064A \u0644\u0639\u0628\u0629 \u0627\u0644\u0631\u0648\u0644\u064A\u062A \u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0645\u0631\u0627\u0647\u0646\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u062C\u0645\u0648\u0639\u0627\u062A \u0648\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0641\u0631\u062F\u064A\u0629 \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0648\u0627\u0644\u0635\u0641\u0648\u0641 \u0648\u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0627\u0644\u0643\u0631\u0629 \u062A\u0647\u0628\u0637 \u0639\u0644\u0649 \u0623\u0631\u0642\u0627\u0645 \u0641\u0631\u062F\u064A\u0629 \u0623\u0648 \u0632\u0648\u062C\u064A\u0629. \u064A\u062E\u062A\u0644\u0641 \u0645\u0628\u0644\u063A \u0627\u0644\u062F\u0641\u0639 \u0648\u0641\u0642\u064B\u0627 \u0644\u0645\u0627 \u062A\u0631\u0627\u0647\u0646 \u0639\u0644\u064A\u0647. \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0632\u0648\u062C\u064A\u0629 \u0648\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0641\u0631\u062F\u064A\u0629\u060C \u064A\u0643\u0648\u0646 \u0645\u062C\u0645\u0648\u0639 \u0627\u0644\u0645\u062F\u0641\u0648\u0639\u0627\u062A \u0645\u0646 1 \u0625\u0644\u0649 1\u060C \u0648\u0647\u0648 \u0645\u0627 \u064A\u0646\u0637\u0628\u0642 \u0639\u0644\u0649 \u0627\u0644\u0623\u062D\u0645\u0631 \u0623\u0648 \u0627\u0644\u0623\u0633\u0648\u062F.</p>
  <p>\u0647\u0646\u0627\u0643 \u0623\u064A\u0636\u064B\u0627 \u0646\u0637\u0627\u0642 \u0645\u062E\u062A\u0644\u0641 \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0645\u0631\u0627\u0647\u0646\u0629 \u0639\u0644\u064A\u0647 \u0647\u0646\u0627. \u064A\u062E\u062A\u0644\u0641 \u0627\u0644\u0639\u0627\u0626\u062F \u0628\u0646\u0627\u0621\u064B \u0639\u0644\u0649 \u0627\u0644\u062D\u0642\u0644 \u0627\u0644\u0630\u064A \u062A\u062E\u062A\u0627\u0631\u0647.</p>
  <p>\u0627\u0644\u0643\u0631\u0627\u0628\u0633 \u0647\u064A \u0644\u0639\u0628\u0629 \u0646\u0631\u062F \u064A\u0631\u0627\u0647\u0646 \u0641\u064A\u0647\u0627 \u0627\u0644\u0644\u0627\u0639\u0628 \u0639\u0644\u0649 \u0646\u062A\u064A\u062C\u0629 \u0646\u0631\u062F\u064A\u0646. \u064A\u0628\u062F\u0648 \u0627\u0644\u0623\u0645\u0631 \u0628\u0633\u064A\u0637\u064B\u0627 \u062C\u062F\u064B\u0627 \u0648\u0644\u0643\u0646 \u0631\u0628\u0645\u0627 \u064A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u0628\u0639\u0636 \u0627\u0644\u0634\u0631\u062D \u0644\u0641\u0647\u0645 \u0643\u064A\u0641\u064A\u0629 \u0644\u0639\u0628 \u0627\u0644\u0644\u0639\u0628\u0629. \u0645\u064A\u0632\u0629 \u0644\u0639\u0628\u0629 \u0627\u0644\u0643\u0631\u0627\u0628\u0633 \u0647\u064A \u0623\u0646 \u0627\u0644\u0646\u0631\u062F \u0647\u0648 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0641\u0642\u0637 \u0644\u0644\u0639\u0628 \u060C \u0644\u0630\u0644\u0643 \u064A\u0645\u0643\u0646\u0643 \u0628\u0633\u0647\u0648\u0644\u0629 \u0644\u0639\u0628 \u0643\u0631\u0627\u0628\u0633 \u0637\u0627\u0644\u0645\u0627 \u0644\u062F\u064A\u0643 \u0646\u0631\u062F\u0627\u0646.</p>
  <p>\u0625\u0630\u0627 \u0643\u0646\u062A \u0642\u062F \u0630\u0647\u0628\u062A \u0625\u0644\u0649 \u0643\u0627\u0632\u064A\u0646\u0648\u060C \u0641\u0623\u0646\u062A \u062A\u0639\u0631\u0641 \u0643\u064A\u0641 \u062A\u0634\u0639\u0631. \u064A\u0645\u0646\u062D\u0643 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u0642\u0644\u064A\u0644 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u0634\u0639\u0648\u0631. \u0641\u064A \u0628\u0639\u0636 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A\u060C \u0644\u062F\u064A\u0643 \u0641\u0631\u0635\u0629 \u0644\u0644\u062F\u0631\u062F\u0634\u0629 \u0645\u0639 \u0627\u0644\u0645\u0636\u064A\u0641 \u0639\u0644\u0649 \u0637\u0648\u0644 \u0627\u0644\u0637\u0631\u064A\u0642. \u0625\u0646\u0647\u0627 \u062A\u0648\u0641\u0631 \u0627\u0644\u0625\u062B\u0627\u0631\u0629 \u0648\u0627\u0644\u0641\u0631\u062D \u0648\u0631\u0628\u0645\u0627 \u0628\u0639\u0636 \u0627\u0644\u0625\u062D\u0628\u0627\u0637 \u0644\u0644\u0639\u0628 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u060C \u0627\u0639\u062A\u0645\u0627\u062F\u064B\u0627 \u0639\u0644\u0649 \u0646\u062A\u064A\u062C\u0629 \u0627\u0644\u0644\u0639\u0628\u0629.</p>
  <p>\u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0631\u063A\u0628 \u0641\u064A \u0644\u0639\u0628 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u060C \u0641\u064A\u062C\u0628 \u0639\u0644\u064A\u0643 \u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0644\u062F\u0649 \u0623\u062D\u062F \u0645\u0632\u0648\u062F\u064A \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0630\u064A\u0646 \u064A\u0642\u062F\u0645\u0648\u0646 \u0647\u0630\u0627. \u0645\u0646 \u0627\u0644\u0633\u0647\u0644 \u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0641\u064A \u0634\u0631\u0643\u0629 \u0623\u0644\u0639\u0627\u0628 \u0623\u062C\u0646\u0628\u064A\u0629 \u060C \u0648\u0644\u0627 \u062A\u0642\u0648\u0645 \u0625\u0644\u0627 \u0628\u0645\u0644\u0621 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0639\u0646\u0643 \u0641\u0642\u0637. \u0628\u0639\u062F \u0630\u0644\u0643\u060C \u062A\u0642\u0648\u0645 \u0628\u0625\u064A\u062F\u0627\u0639 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0623\u0648 \u0623\u064A \u0634\u0643\u0644 \u0622\u062E\u0631 \u0645\u0646 \u0623\u0634\u0643\u0627\u0644 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u062D\u0642\u064A\u0642\u064A \u0648\u062A\u0628\u062F\u0623 \u0627\u0644\u0644\u0639\u0628.</p>
  <p>\u064A\u062A\u0648\u0642\u0639 \u0644\u0627\u0639\u0628\u0648 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0623\u0646 \u064A\u0642\u062F\u0645 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0645\u0628\u0627\u0634\u0631\u0629. \u0645\u0646 \u0627\u0644\u0634\u0627\u0626\u0639 \u062C\u062F\u064B\u0627 \u0644\u0639\u0628 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u062D\u064A\u0629 \u0628\u062D\u064A\u062B \u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0647\u0630\u0627 \u0641\u064A \u0646\u0637\u0627\u0642 \u0643\u0644 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A.</p>
  <p>\u0647\u0646\u0627\u0643 \u0639\u062F\u0629 \u0623\u0646\u0648\u0627\u0639 \u0645\u0646 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0644\u0639\u0628\u0647\u0627 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A\u060C \u0648\u062A\u0639\u062A\u0628\u0631 \u0644\u0639\u0628\u0629 \u0627\u0644\u0631\u0648\u0644\u064A\u062A \u0648\u0627\u0644\u0628\u0644\u0627\u0643 \u062C\u0627\u0643 \u0623\u0643\u062B\u0631 \u0623\u0634\u0643\u0627\u0644 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0634\u064A\u0648\u0639\u064B\u0627. \u0648\u0644\u0643\u0646 \u0647\u0646\u0627\u0643 \u0623\u064A\u0636\u064B\u0627 \u0623\u0644\u0639\u0627\u0628 \u0645\u062B\u0644 Monopoly \u060C \u0648\u0633\u062A\u0635\u0628\u062D \u0645\u0644\u064A\u0648\u0646\u064A\u0631\u064B\u0627 \u0648\u062A\u062F\u0648\u064A\u0631 \u0627\u0644\u0639\u062C\u0644\u0627\u062A \u064A\u0645\u0643\u0646\u0643 \u0644\u0639\u0628\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629.</p>
  <p>\u0639\u0627\u062F\u0629\u064B \u0645\u0627 \u062A\u0643\u0648\u0646 \u0627\u062E\u062A\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0636\u062E\u0645\u064B\u0629\u060C \u0648\u0644\u0643\u0646 \u0639\u0644\u064A\u0643 \u0623\u0646 \u062A\u0639\u0631\u0641 \u0623\u0646\u0647 \u064A\u062E\u062A\u0644\u0641 \u0645\u0646 \u0643\u0627\u0632\u064A\u0646\u0648 \u0625\u0644\u0649 \u0643\u0627\u0632\u064A\u0646\u0648\u060C \u0644\u0630\u0644\u0643 \u0644\u0646 \u062A\u0642\u0648\u0645 \u062F\u0627\u0626\u0645\u064B\u0627 \u0628\u0627\u064A\u062C\u0627\u062F \u0646\u0641\u0633 \u0623\u0644\u0639\u0627\u0628 \u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0643\u0631\u064A\u0628\u062A\u0648 \u0639\u0644\u0649 \u0645\u0648\u0627\u0642\u0639 \u0643\u0627\u0632\u064A\u0646\u0648 \u0643\u0631\u064A\u0628\u062A\u0648 \u0645\u062E\u062A\u0644\u0641\u0629. \u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u0633\u0628\u0628 \u0641\u064A \u0625\u062E\u0628\u0627\u0631\u0646\u0627 \u0644\u0643 \u0639\u0646\u062F \u0625\u0639\u0637\u0627\u0626\u0643 \u0646\u0635\u0627\u0626\u062D \u062D\u0648\u0644 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u062A\u064A \u0633\u062A\u0644\u0639\u0628 \u0641\u064A\u0647\u0627\u060C \u0623\u0648 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0644\u0639\u0628 \u0641\u064A\u0647\u0627 \u060C \u0648\u0644\u0643\u0646 \u0643\u064A\u0641\u064A\u0629 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648 \u0627\u0644\u0645\u062B\u0627\u0644\u064A \u0644\u0643 \u0644\u0625\u0644\u0642\u0627\u0621 \u0646\u0638\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u064A\u0647\u0627 \u0641\u064A \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648.</p>
  <p>\u0648\u062A\u0630\u0643\u0631 \u0623\u0646 \u062A\u062A\u062D\u0642\u0642 \u0645\u0646 \u0646\u0648\u0639 \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062A \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u064A\u0647\u0627. \u0644\u0627 \u062A\u0645\u0646\u062D\u0643 \u062C\u0645\u064A\u0639 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0645\u0643\u0627\u0641\u0623\u0629 \u0625\u064A\u062F\u0627\u0639 \u060C \u0644\u0643\u0646\u0647\u0627 \u0633\u062A\u0645\u0646\u062D\u0643 \u0645\u0643\u0627\u0641\u0622\u062A \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u062D\u0645\u064A\u0644. \u0644\u0630\u0644\u0643 \u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0645\u0643\u0627\u0641\u0622\u062A \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u062D\u0645\u064A\u0644 \u0648\u0645\u0643\u0627\u0641\u0622\u062A \u0639\u062F\u0645 \u0627\u0644\u0625\u064A\u062F\u0627\u0639 \u0625\u0630\u0627 \u0644\u0645 \u062A\u062A\u062D\u0642\u0642 \u062C\u064A\u062F\u064B\u0627 \u0642\u0628\u0644 \u0623\u0646 \u062A\u0628\u062F\u0623. \u0648\u0625\u0630\u0627 \u0643\u0646\u062A \u0645\u062D\u0638\u0648\u0638\u064B\u0627 \u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u062A\u0642\u062F\u0645 \u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0646\u0642\u062F\u064A \u064A\u0648\u0645\u064A\u064B\u0627.</p>
  

  <h2>\u0647\u0644 \u064A\u0645\u0643\u0646\u0646\u064A \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0647\u0627\u062A\u0641 \u0645\u062D\u0645\u0648\u0644 \u0623\u0648 \u062C\u0647\u0627\u0632 \u0644\u0648\u062D\u064A\u061F</h2>
  <p>\u0644\u0646\u0641\u062A\u0631\u0636 \u0623\u0646\u0643 \u062A\u0631\u064A\u062F \u0627\u0644\u0644\u0639\u0628 \u0641\u064A \u0623\u0641\u0636\u0644 \u0627\u0644\u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A. \u0641\u064A \u0647\u0630\u0647 \u0627\u0644\u062D\u0627\u0644\u0629\u060C \u062A\u0631\u064A\u062F\u0647\u0645 \u062C\u0645\u064A\u0639\u064B\u0627 \u0623\u0646 \u064A\u0643\u0648\u0646\u0648\u0627 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0645\u062A\u0646\u0642\u0644\u0629\u060C \u0644\u0645\u062C\u0631\u062F \u0627\u0644\u0627\u0633\u062A\u0645\u062A\u0627\u0639 \u0628\u0645\u062A\u0639\u0629 \u0627\u0644\u0644\u0639\u0628 \u0641\u064A \u0623\u064A \u0648\u0642\u062A \u0648\u0641\u064A \u0623\u064A \u0645\u0643\u0627\u0646 \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u0630\u064A \u062A\u0631\u064A\u062F \u0641\u064A\u0647 \u0627\u0644\u0644\u0639\u0628.</p>
  <p>\u062A\u062D\u0635\u0644 \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0645\u0631\u0627\u0647\u0646\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u062F\u0645 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u062C\u0648\u0627\u0644 \u0639\u0644\u0649 \u0639\u062F\u062F \u0645\u0646 \u0627\u0644\u0632\u064A\u0627\u0631\u0627\u062A \u0641\u064A \u064A\u0648\u0645 \u0648\u0627\u062D\u062F \u0623\u0643\u062B\u0631 \u0645\u0646 \u062A\u0644\u0643 \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0642\u062F\u0645 \u0643\u0627\u0632\u064A\u0646\u0648\u0647\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u062C\u0648\u0627\u0644. \u0646\u0639\u0644\u0645 \u062C\u0645\u064A\u0639\u064B\u0627 \u0623\u0646\u0647 \u0644\u0627 \u0623\u062D\u062F \u064A\u0631\u063A\u0628 \u0641\u064A \u0627\u0644\u062C\u0644\u0648\u0633 \u0623\u0645\u0627\u0645 \u0627\u0644\u062D\u0627\u0633\u0648\u0628 \u0627\u0644\u0645\u062D\u0645\u0648\u0644 \u0628\u0639\u062F \u0627\u0644\u0622\u0646 \u0644\u0644\u0639\u0628 \u0627\u0644\u0642\u0645\u0627\u0631 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A. \u0627\u0644\u0623\u0641\u0636\u0644 \u0647\u0648 \u0623\u0646\u0647 \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u062C\u0645\u064A\u0639 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0646\u0632\u064A\u0647\u0629 \u0648\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u062A\u0631\u062D\u064A\u0628 \u0627\u0644\u0631\u0627\u0626\u0639\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u0627\u0647\u0627 \u0639\u0627\u062F\u0629\u064B \u0625\u0630\u0627 \u0643\u0646\u062A \u062A\u0644\u0639\u0628 \u0645\u0646 \u062C\u0647\u0627\u0632 \u062D\u0627\u0633\u0648\u0628 \u0645\u062D\u0645\u0648\u0644.</p>
</div>`;
